-- ================================================================
-- NanashiCollectibles v2 Schema
-- ================================================================
-- Generated by Claude Code — schema audit, design, and this SQL are
-- documented in NanashiCollectibles/CLAUDE.md.
--
-- This script only creates tables. It does NOT create or drop any
-- database, and does NOT touch the existing legacy schema
-- (Database/All.sql). Select your already-created NanashiCollectibles
-- database before running this script — see the placeholder below.
--
-- Character set: utf8mb4 / utf8mb4_unicode_ci throughout — chosen
-- deliberately over newer collations (e.g. utf8mb4_0900_ai_ci) because
-- unicode_ci is supported identically across MySQL 5.7, MySQL 8, and
-- MariaDB 10.x, and is exactly what the existing Database/All.sql
-- already uses successfully. The exact engine/version running this
-- script was not confirmed, so the broadly-compatible option was
-- chosen rather than assuming MySQL 8.
--
-- Money: every monetary column is DECIMAL(10,2). No FLOAT/DOUBLE/INT
-- is used for currency anywhere in this script.
--
-- CHECK constraints: intentionally NONE. MySQL versions before 8.0.16
-- parse but silently ignore CHECK constraints, which would make any
-- reliance on them a false sense of safety on an unconfirmed engine
-- version. Every rule that would have been a CHECK constraint is
-- called out in a comment near the relevant table and must be
-- enforced in backend application/service logic instead.
--
-- Table creation order is real dependency order (parent/lookup tables
-- before the tables that reference them) — no FOREIGN_KEY_CHECKS
-- toggling is used anywhere in this script.
-- ================================================================

-- Select your NanashiCollectibles database before running this script.
-- USE `your_nanashicollectibles_schema`;


-- ================================================================
-- 1. IDENTITY
-- ================================================================

CREATE TABLE users (
  id                 INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  role               VARCHAR(20)   NOT NULL DEFAULT 'user',      -- 'user' | 'vendor' | 'admin' — app-validated, not ENUM, so new roles never need a migration
  name               VARCHAR(100)  NOT NULL,
  email              VARCHAR(100)  NOT NULL,
  phone              VARCHAR(20)   NULL,
  password_hash      VARCHAR(255)  NOT NULL,                     -- bcrypt hash; widened from the legacy 100 chars for headroom
  profile_icon       VARCHAR(255)  NULL,
  status             VARCHAR(20)   NOT NULL DEFAULT 'active',    -- 'active' | 'suspended' | 'deleted' — soft delete, never hard-delete a user with real history
  email_verified_at  TIMESTAMP     NULL,
  last_login_at      TIMESTAMP     NULL,
  created_at         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at         TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_users_email (email),
  UNIQUE KEY uq_users_phone (phone),
  INDEX idx_users_role (role),
  INDEX idx_users_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE password_reset_tokens (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id     INT UNSIGNED NOT NULL,
  token_hash  CHAR(64)     NOT NULL,
  expires_at  DATETIME     NOT NULL,
  used_at     TIMESTAMP    NULL,                                 -- NULL = unused; set when the token is consumed
  created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_password_reset_tokens_user
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  UNIQUE KEY uq_password_reset_tokens_token_hash (token_hash),
  INDEX idx_password_reset_tokens_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ================================================================
-- 2. SHARED REFERENCE / LOOKUP DATA
-- (no foreign keys out; referenced by later modules)
-- ================================================================

CREATE TABLE countries (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name          VARCHAR(100) NOT NULL,
  iso_code      CHAR(2)      NOT NULL,                           -- ISO 3166-1 alpha-2, e.g. 'BN'
  calling_code  VARCHAR(10)  NOT NULL,                           -- e.g. '+673'
  flag          VARCHAR(10)  NULL,                                -- flag emoji, e.g. '🇧🇳'
  created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_countries_iso_code (iso_code),
  INDEX idx_countries_calling_code (calling_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- No seed data included — seed rows require separate approval.

CREATE TABLE product_categories (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name         VARCHAR(100) NOT NULL,
  slug         VARCHAR(120) NOT NULL,
  description  TEXT NULL,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_product_categories_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Intended seed rows (not included): Trading Card Games, TCG Accessories, Collectibles, Gunpla, Drone Parts, Computer Parts.

CREATE TABLE tcg_games (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  slug        VARCHAR(120) NOT NULL,
  status      VARCHAR(20)  NOT NULL DEFAULT 'active',            -- 'active' | 'coming_soon'
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_tcg_games_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Intended seed rows (not included): Digimon, Pokémon, Magic: The Gathering, Cardfight!! Vanguard, Ultraman.

CREATE TABLE esports_games (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  slug        VARCHAR(120) NOT NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_esports_games_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Intended seed row (not included): Apex Legends. Deliberately just a data row, not a schema concept.

CREATE TABLE news_categories (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  slug        VARCHAR(120) NOT NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_news_categories_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Intended seed rows (not included): General, TCG, Esports, Services, Shop, Technology, Collectibles.


-- ================================================================
-- 3. PRODUCTS / SHOP
-- ================================================================

CREATE TABLE products (
  id                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  vendor_id         INT UNSIGNED NOT NULL,
  category_id       INT UNSIGNED NOT NULL,
  tcg_game_id       INT UNSIGNED NULL,                           -- only set when category_id is a TCG-related category
  name              VARCHAR(150) NOT NULL,
  slug              VARCHAR(180) NOT NULL,
  code              VARCHAR(100) NULL,                            -- SKU
  description       LONGTEXT NULL,
  condition_label   VARCHAR(50) NULL,
  price             DECIMAL(10,2) NOT NULL,                       -- fixed from the legacy INT column — was unable to store cents
  stock_quantity    INT UNSIGNED NOT NULL DEFAULT 0,               -- current stock; single source of truth (see inventory_movements)
  status            VARCHAR(20) NOT NULL DEFAULT 'active',        -- 'active' | 'archived' — archive instead of deleting products with history
  created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_products_vendor
    FOREIGN KEY (vendor_id) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT fk_products_category
    FOREIGN KEY (category_id) REFERENCES product_categories(id) ON DELETE RESTRICT,
  CONSTRAINT fk_products_tcg_game
    FOREIGN KEY (tcg_game_id) REFERENCES tcg_games(id) ON DELETE SET NULL,
  UNIQUE KEY uq_products_slug (slug),
  INDEX idx_products_vendor (vendor_id),
  INDEX idx_products_category (category_id),
  INDEX idx_products_tcg_game (tcg_game_id),
  INDEX idx_products_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- vendor_id uses ON DELETE RESTRICT rather than CASCADE: a vendor account should not be
-- hard-deletable while it still owns products (and, transitively, inventory history) —
-- archive the vendor (users.status = 'deleted') instead. This is an extension of the same
-- "archive, don't cascade away business records" principle applied to inventory_movements
-- below; flagging it here as an assumption since it wasn't spelled out explicitly.

CREATE TABLE product_images (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id  INT UNSIGNED NOT NULL,
  image_url   LONGTEXT NOT NULL,
  sort_order  INT UNSIGNED NOT NULL DEFAULT 0,
  is_primary  TINYINT(1) NOT NULL DEFAULT 0,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_product_images_product
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
  INDEX idx_product_images_product (product_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ON DELETE CASCADE here is intentional and different from inventory_movements below:
-- images are meaningless without their product, so they should disappear with it.

CREATE TABLE inventory_movements (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  product_id  INT UNSIGNED NOT NULL,
  delta       INT NOT NULL,                                      -- signed: positive (restock) or negative (sale/adjustment)
  reason      VARCHAR(100) NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_inventory_movements_product
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  INDEX idx_inventory_movements_product (product_id),
  INDEX idx_inventory_movements_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ON DELETE RESTRICT (not CASCADE): a product with recorded stock history can never be
-- physically deleted — MySQL will reject the DELETE. The application must set
-- products.status = 'archived' instead. A product with zero movements can still be
-- hard-deleted freely, since there is no history to lose.
--
-- BACKEND REQUIREMENT (not implemented by this script): every write that changes
-- products.stock_quantity must, in the same database transaction, also insert the
-- matching inventory_movements row. These two writes must not be able to partially
-- succeed. products.stock_quantity is UNSIGNED and must never be allowed to go negative;
-- application code must validate/clamp before committing, since the column type alone
-- only rejects negative values after the fact (the statement would simply fail).


-- ================================================================
-- 4. TCG
-- ================================================================

CREATE TABLE deck_lists (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  tcg_game_id  INT UNSIGNED NOT NULL,
  created_by   INT UNSIGNED NULL,
  name         VARCHAR(255) NOT NULL,
  archetype    VARCHAR(100) NULL,
  format       VARCHAR(100) NULL,
  pilot        VARCHAR(100) NULL,
  description  TEXT NULL,
  key_cards    TEXT NULL,
  win_rate     DECIMAL(5,2) NULL,
  popularity   INT UNSIGNED NULL,
  avg_cost     DECIMAL(10,2) NULL,
  featured     TINYINT(1) NOT NULL DEFAULT 0,
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_deck_lists_tcg_game
    FOREIGN KEY (tcg_game_id) REFERENCES tcg_games(id) ON DELETE RESTRICT,
  CONSTRAINT fk_deck_lists_created_by
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL,
  INDEX idx_deck_lists_tcg_game (tcg_game_id),
  INDEX idx_deck_lists_archetype (archetype),
  INDEX idx_deck_lists_featured (featured)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Postponed, not in this script: cards, singles, deck_list_items — no implemented
-- functionality needs them yet.


-- ================================================================
-- 5. RVS ESPORTS / TOURNAMENT
-- ================================================================

CREATE TABLE tournaments (
  id                     INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  esports_game_id        INT UNSIGNED NOT NULL,
  name                   VARCHAR(255) NOT NULL,
  slug                   VARCHAR(280) NOT NULL,
  description            LONGTEXT NULL,
  location               VARCHAR(255) NULL,
  entry_fee              DECIMAL(10,2) NULL,
  organizer              VARCHAR(100) NULL,
  rules                  LONGTEXT NULL,
  registration_deadline  TIMESTAMP NULL,
  registration_type      VARCHAR(20) NOT NULL DEFAULT 'individual', -- 'individual' | 'team' — see note below
  team_size              INT UNSIGNED NULL,                          -- required (app-level) when registration_type = 'team'
  max_entries            INT UNSIGNED NULL,                          -- max registrants (individual) OR max teams (team)
  status                 VARCHAR(20) NOT NULL DEFAULT 'draft',       -- draft|open|closed|completed|cancelled
  start_date             TIMESTAMP NULL,
  end_date               TIMESTAMP NULL,
  created_at             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_tournaments_esports_game
    FOREIGN KEY (esports_game_id) REFERENCES esports_games(id) ON DELETE RESTRICT,
  UNIQUE KEY uq_tournaments_slug (slug),
  INDEX idx_tournaments_esports_game (esports_game_id),
  INDEX idx_tournaments_status (status),
  INDEX idx_tournaments_start_date (start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- BACKEND REQUIREMENT (not a DB-level CHECK, deliberately — see file header): application
-- code must enforce that team_size IS NOT NULL when registration_type = 'team', and NULL
-- when registration_type = 'individual'.

CREATE TABLE tournament_registrations (
  id             INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  tournament_id  INT UNSIGNED NOT NULL,
  user_id        INT UNSIGNED NULL,
  guest_name     VARCHAR(100) NULL,                                -- set when user_id IS NULL (guest participant)
  nickname       VARCHAR(100) NULL,
  status         VARCHAR(20) NOT NULL DEFAULT 'registered',        -- registered|checked_in|withdrawn|disqualified
  registered_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_registrations_tournament
    FOREIGN KEY (tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE,
  CONSTRAINT fk_registrations_user
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  UNIQUE KEY uq_registrations_tournament_user (tournament_id, user_id), -- MySQL allows multiple NULL user_id per tournament, so this never blocks guests
  UNIQUE KEY uq_registrations_id_tournament (id, tournament_id),        -- composite candidate key, exists only so tournament_teams/tournament_team_members below can enforce cross-table tournament consistency via plain FKs
  INDEX idx_registrations_tournament (tournament_id),
  INDEX idx_registrations_user (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE tournament_teams (
  id                       INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  tournament_id            INT UNSIGNED NOT NULL,
  name                     VARCHAR(255) NOT NULL,
  captain_registration_id  INT UNSIGNED NULL,
  status                   VARCHAR(20) NOT NULL DEFAULT 'registered',
  created_at               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at               TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_teams_tournament
    FOREIGN KEY (tournament_id) REFERENCES tournaments(id) ON DELETE CASCADE,
  -- Composite FK: guarantees the captain's registration belongs to THIS SAME tournament.
  -- (It does not, by itself, guarantee the captain is a member of THIS SPECIFIC team —
  -- see the backend requirement note below.)
  CONSTRAINT fk_teams_captain_registration
    FOREIGN KEY (captain_registration_id, tournament_id)
    REFERENCES tournament_registrations(id, tournament_id) ON DELETE SET NULL,
  UNIQUE KEY uq_teams_tournament_name (tournament_id, name),
  UNIQUE KEY uq_teams_id_tournament (id, tournament_id),           -- composite candidate key for tournament_team_members below
  INDEX idx_teams_tournament (tournament_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE tournament_team_members (
  id               INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  tournament_id    INT UNSIGNED NOT NULL,                          -- redundant by design: exists purely so both composite FKs below can be enforced by MySQL itself
  team_id          INT UNSIGNED NOT NULL,
  registration_id  INT UNSIGNED NOT NULL,
  joined_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  -- Enforces: "a registration assigned to a team must belong to the same tournament as that team."
  CONSTRAINT fk_team_members_team
    FOREIGN KEY (team_id, tournament_id)
    REFERENCES tournament_teams(id, tournament_id) ON DELETE CASCADE,
  CONSTRAINT fk_team_members_registration
    FOREIGN KEY (registration_id, tournament_id)
    REFERENCES tournament_registrations(id, tournament_id) ON DELETE CASCADE,
  UNIQUE KEY uq_team_members_registration (registration_id),       -- a registration belongs to at most one team, ever
  INDEX idx_team_members_team (team_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Both cross-table tournament-consistency rules you asked for are enforced by MySQL
-- itself via the composite foreign keys above — no triggers used:
--   1. A team_member's registration is guaranteed to be in the same tournament as its team
--      (fk_team_members_team + fk_team_members_registration both key off tournament_id).
--   2. A team's captain_registration_id is guaranteed to be in the same tournament as the
--      team (fk_teams_captain_registration).
-- NOT enforced at the database level (would require a trigger to do cleanly, and none was
-- added per your instruction to avoid triggers unless necessary) — MUST be enforced in
-- backend service logic:
--   - That a team's captain_registration_id is actually a MEMBER of that specific team
--     (i.e. has a row in tournament_team_members for that team_id), not just any
--     registration in the same tournament. Recommended pattern: only allow setting a
--     captain from within the same transaction that inserts/has already inserted the
--     corresponding tournament_team_members row, and validate the membership row exists
--     first.
--   - Whenever inserting into this table, the application must set tournament_id to the
--     same value as the referenced team's (and registration's) tournament_id — trivial
--     (SELECT it from either parent), but not automatic.
-- BACKEND REQUIREMENT (transactional): creating a team registration — the team row, each
-- member's registration row, each tournament_team_members row, and the captain assignment —
-- must happen in a single database transaction so it cannot partially succeed.


-- ================================================================
-- 6. TRADES
-- ================================================================

CREATE TABLE trade_listings (
  id                INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id           INT UNSIGNED NOT NULL,
  tcg_game_id       INT UNSIGNED NULL,
  product_id        INT UNSIGNED NULL,
  title             VARCHAR(255) NOT NULL,
  condition_label   VARCHAR(100) NULL,
  listing_type      VARCHAR(20) NOT NULL DEFAULT 'trade',          -- 'trade' | 'sale'
  want_text         TEXT NULL,
  notes             TEXT NULL,
  status            VARCHAR(20) NOT NULL DEFAULT 'active',         -- 'active' | 'cancelled' | 'completed'
  created_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_trade_listings_user
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_trade_listings_tcg_game
    FOREIGN KEY (tcg_game_id) REFERENCES tcg_games(id) ON DELETE SET NULL,
  CONSTRAINT fk_trade_listings_product
    FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL,
  INDEX idx_trade_listings_user (user_id),
  INDEX idx_trade_listings_tcg_game (tcg_game_id),
  INDEX idx_trade_listings_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Postponed, not in this script: trade_offers.


-- ================================================================
-- 7. CONTENT
-- ================================================================

CREATE TABLE news (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  category_id   INT UNSIGNED NOT NULL,
  tcg_game_id   INT UNSIGNED NULL,                                 -- optional: only for game-specific articles
  title         VARCHAR(255) NOT NULL,
  slug          VARCHAR(280) NOT NULL,
  content       LONGTEXT NULL,
  image_url     LONGTEXT NULL,
  author        VARCHAR(100) NULL,
  tags          VARCHAR(255) NULL,
  status        VARCHAR(20) NOT NULL DEFAULT 'draft',              -- 'draft' | 'published'
  published_at  TIMESTAMP NULL,
  created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_news_category
    FOREIGN KEY (category_id) REFERENCES news_categories(id) ON DELETE RESTRICT,
  CONSTRAINT fk_news_tcg_game
    FOREIGN KEY (tcg_game_id) REFERENCES tcg_games(id) ON DELETE SET NULL,
  UNIQUE KEY uq_news_slug (slug),
  INDEX idx_news_category (category_id),
  INDEX idx_news_tcg_game (tcg_game_id),
  INDEX idx_news_status (status),
  INDEX idx_news_published_at (published_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ================================================================
-- 8. SERVICES
-- ================================================================

CREATE TABLE services (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name         VARCHAR(150) NOT NULL,
  slug         VARCHAR(180) NOT NULL,
  category     VARCHAR(50) NULL,                                   -- e.g. 'drone', 'web_development', 'application_development'
  summary      VARCHAR(500) NULL,
  description  LONGTEXT NULL,
  status       VARCHAR(20) NOT NULL DEFAULT 'active',
  created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_services_slug (slug)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Intended seed rows (not included): Drone Services, Website Development, Application Development.

CREATE TABLE enquiries (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  service_id  INT UNSIGNED NULL,                                   -- nullable: not every enquiry is about a service
  topic       VARCHAR(30) NOT NULL,                                -- 'general' | 'shop' | 'tcg' | 'esports' | 'service' — app-validated, open to future topics without a schema change
  name        VARCHAR(100) NOT NULL,
  email       VARCHAR(100) NOT NULL,
  phone       VARCHAR(20) NULL,
  message     TEXT NOT NULL,
  status      VARCHAR(20) NOT NULL DEFAULT 'new',                  -- 'new' | 'in_progress' | 'resolved' | 'closed'
  created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_enquiries_service
    FOREIGN KEY (service_id) REFERENCES services(id) ON DELETE SET NULL,
  INDEX idx_enquiries_service (service_id),
  INDEX idx_enquiries_topic (topic),
  INDEX idx_enquiries_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ================================================================
-- END OF NanashiCollectibles v2 SCHEMA
-- 19 tables. No data, no destructive statements, nothing executed.
-- ================================================================
